 const auto& connected_nominal=connected.originalAssembly().originalNormalization().originalForecast();need(connected_nominal.sessionActive()&&expected_prediction_owner_.matches(connected_nominal.authenticOwner()),"connected nominal prediction must belong to designated still-active Session");
 validation_boundary_=completed_.completed_tick;
 // Private owner resets and recomputes the public report; passed is never an input.
 report=phase5_pilot_candidate_validation_v1::Assessment{};report.reach_bound=structural_reach_bound_;
 phase5_pilot_candidate_validation_v1::assess(actual,connected,candidate,value,*warmup_robot_,*warmup_geometry_,speed,report);if(!report.passed||!report.error.empty())return {};
 current(actual,ObservationClock::OfflineFrozenSimulationBoundary);std::vector<mjtNum> now(actual.integrationAfter().size());++facts_.get_state;mj_getState(model_.get(),state_.get(),now.data(),mjSTATE_INTEGRATION);need(bits(now,actual.integrationAfter()),"validation must leave exact current integration unchanged");
 need(candidate.forensicFirstPreview().has_value(),"nativeaccepted first preview mandatory");const auto& p=*candidate.forensicFirstPreview();need(std::isfinite(p.b)&&std::isfinite(p.s_next)&&std::isfinite(p.r_next)&&p.s_next>=0&&p.s_next<=1&&p.r_next>=0&&p.r_next<=.2,"actual bounded firstpreview progress");
 auto token=std::unique_ptr<ValidatedCandidate>(new ValidatedCandidate);token->owner=owner_token_;token->boundary=actual;token->nominal_digest=value.nominalInvocationSha256();token->value=std::make_unique<live::OwnedCandidateValue>(std::move(value));token->C=p.C_next;token->w=p.w_next;token->alpha=p.implied_alpha;token->s=p.s_next;token->r=p.r_next;token->b=p.b;token->speed=connected.retainedLimits().physical_speed;const auto& ranges=connected.originalAssembly().originalNormalization().originalForecast().actualContext().ranges();for(int j=0;j<7;++j){token->q_lower[j]=std::max(warmup_robot_->lowerLimits()(j),ranges.qLower()[j])+.005;token->q_upper[j]=std::min(warmup_robot_->upperLimits()(j),ranges.qUpper()[j])-.005;}return token;
